public static int calculateTimeNeeded(int N) {
    if (N <= 0) {
        throw new IllegalArgumentException("Number of people must be greater than zero.");
    }
    // The time needed is (N/2) * 2 which simplifies to N-1 if N is odd, and N-2 if N is even.
    // However, the pattern suggests it's always N-2 for N >= 4, and 2 for N=3, 4 for N=5, etc.
