public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, result);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (int i = 0; i < strings.size(); i++) {
        String s1 = strings.get(i);
        for (int start = 0; start < s1.length(); start++) {
            for (int end = start + 1; end <= s1.length(); end++) {
                String substring = s1.substring(start, end);
                String inverse = new StringBuilder(substring).reverse().toString();
                boolean isCommonSubstring = true;
                for (String s : strings) {
                    if (!s.contains(substring) && !s.contains(inverse)) {
                        isCommonSubstring = false;
                        break;
                    }
                }
                if (isCommonSubstring) {
                    maxLength = Math.max(maxLength, substring.length());
                }
            }
        }
    }

    return maxLength;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int numRows = grid.length;
    int numCols = grid[0].length;
    boolean[][] visited = new boolean[numRows][numCols];
    int depositCount = 0;

    for (int row = 0; row < numRows; row++) {
        for (int col = 0; col < numCols; col++) {
            if (grid[row][col] == '@' && !visited[row][col]) {
                dfs(grid, visited, row, col);
                depositCount++;
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    int[] rowDirections = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] colDirections = {-1, 0, 1, -1, 1, -1, 0, 1};

    visited[row][col] = true;

    for (int i = 0; i < 8; i++) {
        int newRow = row + rowDirections[i];
        int newCol = col + colDirections[i];

        if (isValidCell(grid, visited, newRow, newCol)) {
            dfs(grid, visited, newRow, newCol);
        }
    }
}

private static boolean isValidCell(char[][] grid, boolean[][] visited, int row, int col) {
    return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length
            && grid[row][col] == '@' && !visited[row][col];
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // The formula to calculate the maximum number of regions
    // when N triangles are added to the plane is:
    // R(N) = 2 + 3 * N + 2 * combinations(N, 2)
    // where combinations(N, 2) is the binomial coefficient N choose 2
    // which is calculated as N * (N - 1) / 2
    return 2 + 3 * N + 2 * (N * (N - 1) / 2);
}

