public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(start[0], start[1], end[0], end[1], visited, paths, n);
    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, boolean[][] visited, int[][] paths, int n) {
    if (x == endX && y == endY) {
        return true;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        if (path[0] == x && path[1] == y && !visited[path[2]][path[3]]) {
            if (dfs(path[2], path[3], endX, endY, visited, paths, n)) {
                return true;
            }
        } else if (path[2] == x && path[3] == y && !visited[path[0]][path[1]]) {
            if (dfs(path[0], path[1], endX, endY, visited, paths, n)) {
                return true;
            }
        }
    }

    return false;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null");
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    boolean[] usedLetters = new boolean[26];
    int commonCount = 0;

    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) != -1 && !usedLetters[c - 'A']) {
            commonCount++;
            usedLetters[c - 'A'] = true;
        }
    }

    int totalLength = word1.length() + word2.length();
    int gcd = gcd(commonCount, totalLength);

    return String.format("appx(%s, %s) = %d/%d", word1, word2, commonCount / gcd, totalLength / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] parts = date.split(" ");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Date format should be 'MM dd yyyy'");
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12 || day < 1 || day > 31) {
            throw new IllegalArgumentException("Invalid month or day");
        }

        String[] months = {"", "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
        String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(year, month - 1, day);

        int dayOfWeek = calendar.get(java.util.Calendar.DAY_OF_WEEK);
        String weekday = weekdays[dayOfWeek - 1];
