        throw new IllegalArgumentException("Invalid date format", e);
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        throw new IllegalArgumentException("Input array must have at least two elements.");
    }

    Map<Integer, Integer> numMap = new HashMap<>();

    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (numMap.containsKey(complement)) {
            return new int[] { numMap.get(complement), i };
        }
        numMap.put(nums[i], i);
    }

    throw new IllegalArgumentException("No two sum solution");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }

    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (nums[mid] == target) {
            return mid;
        }

        if (nums[left] <= nums[mid]) {
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty.");
    }

    int n = arr.length;
    int trimSize = n / 20; // 5% of the array size

    // Sort the array
    java.util.Arrays.sort(arr);

    // Calculate the sum of the elements excluding the smallest and largest 5%
    double sum = 0;
    for (int i = trimSize; i < n - trimSize; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    return sum / (n - 2 * trimSize);
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }

    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Ensure non-negative remainder
        remainderCount[remainder]++;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    if (k % 2 == 0 && remainderCount[k / 2] % 2 != 0) {
        return false;
    }

    return remainderCount[0] % 2 == 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || edges.length != n - 1 || hasApple.length != n) {
        throw new IllegalArgumentException("Invalid input");
    }

    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }

    return dfs(0, -1, tree, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> tree, boolean[] hasApple) {
    int totalTime = 0;
    int childTime = 0;

    for (int child : tree.get(node)) {
        if (child == parent) {
            continue;
        }
        childTime = dfs(child, node, tree, hasApple);
        if (childTime > 0 || hasApple[child]) {
            totalTime += childTime + 2;
        }
    }

    return totalTime;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] charCount = new int[26];
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        for (int i = 0; i < 26; i++) {
            if (charCount[i] > 0) {
                result.append((char) (i + 'a'));
                charCount[i]--;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (charCount[i] > 0) {
                result.append((char) (i + 'a'));
                charCount[i]--;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i / 2, n / 2); j >= 1; j--) {
            for (int k = sum; k >= num; k--) {
                dp[i][j][k] = dp[i - 1][j][k] || dp[i - 1][j - 1][k - num];
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if ((sum * j) % n == 0 && dp[n][j][(sum * j) / n]) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two elements.");
    }

    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
