public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    for (int i = 0; i <= 9; i++) {
        bfsSearch(low, high, i, result);
    }

    Collections.sort(result);
    return result;
}

private static void bfsSearch(int low, int high, int number, List<Integer> result) {
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(number);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current >= low && current <= high) {
            result.add(current);
        }
        if (current == 0 || current > high) {
            continue;
        }

        int lastDigit = current % 10;
        if (lastDigit > 0) {
            int nextNumber = current * 10 + (lastDigit - 1);
            if (nextNumber <= high) {
                queue.offer(nextNumber);
            }
        }
        if (lastDigit < 9) {
            int nextNumber = current * 10 + (lastDigit + 1);
            if (nextNumber <= high) {
                queue.offer(nextNumber);
            }
        }
    }
}

public static int countDigitOne(int n) {
