    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Directions: right, down, down-right, down-left
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                dp[i][j][0] = (j > 0) ? dp[i][j - 1][0] + 1 : 1;
                // Vertical
                dp[i][j][1] = (i > 0) ? dp[i - 1][j][1] + 1 : 1;
                // Diagonal
                dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1;
                // Anti-diagonal
                dp[i][j][3] = (i > 0 && j < n - 1) ? dp[i - 1][j + 1][3] + 1 : 1;

                // Update maxLength
                for (int k = 0; k < 4; k++) {
                    maxLength = Math.max(maxLength, dp[i][j][k]);
                }
            }
        }
    }

    return maxLength;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder();
    int count = 0;

    while (n > 0) {
        int digit = n % 10;
        result.append(digit);
        count++;
        n /= 10;

        if (count % 3 == 0 && n > 0) {
            result.append('.');
        }
    }

    return result.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;

    boolean[] used = new boolean[A.length];
    int[] count = new int[1];
    backtrack(A, used, new ArrayList<>(), count);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, List<Integer> current, int[] count) {
    if (current.size() == A.length) {
        count[0]++;
        return;
    }

    Set<Integer> set = new HashSet<>();
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (current.size() > 0 && set.contains(A[i]))) continue;

        if (current.isEmpty() || isPerfectSquare(current.get(current.size() - 1) + A[i])) {
            used[i] = true;
            current.add(A[i]);
            set.add(A[i]);
            backtrack(A, used, current, count);
            used[i] = false;
            current.remove(current.size() - 1);
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;

    for (int i = 0; i <= heights.length; i++) {
        while (!stack.isEmpty() && (i == heights.length || heights[stack.peek()] >= heights[i])) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int r = 0, c = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        if ((r + c) % 2 == 0) { // Moving up
            if (c == n - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else { // Moving down
            if (r == m - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;

    // Find the rightmost digit that is smaller than the digit next to it
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) which is greater than digits[i]
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after position i
    reverse(digits, i + 1, digits.length - 1);

    // Convert the character array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case the number is out of int range
    }
}

private static void reverse(char[] digits, int left, int right) {
    while (left < right) {
        char temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    List<String> result = new ArrayList<>();
    if (n == 1) {
        result.addAll(Arrays.asList("0", "1", "8"));
        return result;
    }

    if (n == 2) {
        result.addAll(Arrays.asList("11", "69", "88", "96"));
        return result;
    }

    List<String> centerSymmetricNumbers = centerSymmetricNumbers(n - 2);
    for (String centerSymmetricNumber : centerSymmetricNumbers) {
        result.add("1" + centerSymmetricNumber + "1");
        result.add("6" + centerSymmetricNumber + "9");
        result.add("8" + centerSymmetricNumber + "8");
        result.add("9" + centerSymmetricNumber + "6");
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Input must be an array of 3 points, each with 2 coordinates.");
    }

    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];

    // Calculate the area of the triangle formed by the three points
    // Area = 0.5 * |x0(y1 - y2) + x1(y2 - y0) + x2(y0 - y1)|
    // If area is 0, the points are collinear and do not form a boomerang
    int area = x0 * (y1 - y2) + x1 * (y2 - y0) + x2 * (y0 - y1);

    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;
    int factor2 = 2, factor3 = 3, factor5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(factor2, Math.min(factor3, factor5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == factor2) {
            index2++;
            factor2 = uglyNumbers[index2] * 2;
        }
        if (nextUglyNumber == factor3) {
            index3++;
            factor3 = uglyNumbers[index3] * 3;
        }
        if (nextUglyNumber == factor5) {
            index5++;
            factor5 = uglyNumbers[index5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    return Math.max(maxEnergy, currentEnergy);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }

    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) {
            return;
        }
        dfs(next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }

    Map<Integer, Integer> frequencyMap = new HashMap<>();

    for (int num : nums) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }

    int uniqueSum = 0;
    for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == 1) {
            uniqueSum += entry.getKey();
        }
    }

    return uniqueSum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        String reversedWord = new StringBuilder(word).reverse().toString();
        result.append(reversedWord);
        if (i < words.length - 1) {
            result.append(" ");
        }
    }

    return result.toString();
}
